class FastAPIException(Exception):
    """
    A base class for exceptions, allows FastAPI to handle and document errors
    from this base class.
    """


class RequestValidationError(FastAPIException):
    def __init__(self, errors: Sequence[Any], *, body: Any = None) -> None:
        self._errors = errors
        self._body = body
        super().__init__(errors=errors, body=body)

    @property
    def errors(self) -> Any:
        return jsonable_encoder(self._errors)

    @property
    def body(self) -> Optional[Any]:
        return self._body


class ResponseValidationError(FastAPIException):
    def __init__(self, errors: Sequence[Any], *, body: Any = None) -> None:
        self._errors = errors
        self._body = body
        super().__init__(errors=errors, body=body)

    @property
    def errors(self) -> Any:
        return jsonable_encoder(self._errors)

    @property
    def body(self) -> Optional[Any]:
        return self._body


